package combo

import (
	"context"
	"fmt"
	"sync"

	"github.com/filecoin-project/bacalhau/pkg/model"
	"github.com/filecoin-project/bacalhau/pkg/publisher"
	"github.com/filecoin-project/bacalhau/pkg/publisher/types"
	"github.com/filecoin-project/bacalhau/pkg/system"
	"github.com/rs/zerolog/log"
)

// FanoutPublisher publishes to multiple publishers in parallel and returns the
// first successful result.
type FanoutPublisher struct {
	publishers []publisher.Publisher
}

func NewFanoutPublisher(publishers ...publisher.Publisher) *FanoutPublisher {
	return &FanoutPublisher{
		publishers: publishers,
	}
}

func (p *FanoutPublisher) IsInstalled(ctx context.Context) (bool, error) {
	for _, pub := range p.publishers {
		installed, err := pub.IsInstalled(ctx)
		if err != nil {
			return false, err
		}
		if !installed {
			return false, nil
		}
	}
	return true, nil
}

func (p *FanoutPublisher) PublishResult(
	ctx context.Context,
	executionID string,
	job model.Job,
	result publisher.ResultPublisher,
) (model.StorageSpec, error) {
	// Create a channel to collect results from each publisher.
	type result struct {
		storageSpec model.StorageSpec
		err         error
	}

	results := make(chan result, len(p.publishers))

	// Launch a goroutine for each publisher.
	var wg sync.WaitGroup
	for _, pub := range p.publishers {
		wg.Add(1)
		go func(pub publisher.Publisher) {
			defer wg.Done()
			storageSpec, err := pub.PublishResult(ctx, executionID, job, result)
			results <- result{storageSpec, err}
		}(pub)
	}

	// Wait for all publishers to finish.
	wg.Wait()
	close(results)

	// Collect results.
	var firstErr error
	var firstSuccess *model.StorageSpec
	for res := range results {
		if res.err != nil {
			if firstErr == nil {
				firstErr = res.err
			}
			continue
		}
		if firstSuccess == nil {
			firstSuccess = &res.storageSpec
		}
	}

	// If we have a successful result, return it.
	if firstSuccess != nil {
		return *firstSuccess, nil
	}

	// If all publishers failed, return the first error.
	return model.StorageSpec{}, firstErr
}

func (p *FanoutPublisher) GetErrorFromPublishResult(ctx context.Context, result model.StorageSpec) error {
	for _, pub := range p.publishers {
		err := pub.GetErrorFromPublishResult(ctx, result)
		if err != nil {
			return err
		}
	}
	return nil
}

